#include <stdio.h>

/* Sayan semafor taklidi: deger > 0 ise gecilir, 0 ise "bloke olurdu". */
static int sem = 3;
static int bekleyen = 0;

static void sem_wait_taklit(int kim) {
    if (sem > 0) {
        sem--;
        printf("  is %d: gecti (sem=%d)\n", kim, sem);
    } else {
        bekleyen++;
        printf("  is %d: BLOKE (bekleyen=%d)\n", kim, bekleyen);
    }
}

static void sem_post_taklit(void) {
    if (bekleyen > 0) {
        bekleyen--;
        printf("  post: bir bekleyen uyandi (bekleyen=%d, sem=%d)\n", bekleyen, sem);
    } else {
        sem++;
        printf("  post: sem arttirildi (sem=%d)\n", sem);
    }
}

int main(void) {
    printf("semafor baslangic degeri = %d\n", sem);
    for (int i = 1; i <= 5; i++) sem_wait_taklit(i);
    printf("ara durum: sem=%d bekleyen=%d\n", sem, bekleyen);
    sem_post_taklit();
    sem_post_taklit();
    sem_post_taklit();
    printf("son durum: sem=%d bekleyen=%d\n", sem, bekleyen);
    return 0;
}

#include <stdio.h>

/* Elf64_Sym kaydi 24 bayttir. */
#define SYM 24

static int sayac = 0;          /* ic baglanti (static): .symtab'da LOCAL  */
int genel = 5;                 /* dis baglanti: .symtab'da GLOBAL         */

static int artir(void) {
    static int yerel = 100;    /* statik omur, blok kapsami, baglanti YOK */
    sayac++;
    yerel++;
    return yerel;
}

int main(void) {
    for (int i = 0; i < 3; i++) {
        int y = artir();
        printf("cagri %d: yerel=%d sayac=%d\n", i + 1, y, sayac);
    }
    unsigned long yerel_s = 1200, genel_s = 1800;
    printf("sembol tablosu: %lu kayit -> %lu bayt\n",
           yerel_s + genel_s, (yerel_s + genel_s) * SYM);
    printf("genel = %d\n", genel);
    return 0;
}

