#include <stdio.h>
#include <string.h>

/* Savunma odakli kopyalama: hedefin boyutu HER ZAMAN biliniyor ve
   tasma olusmadan ONCE reddediliyor. */
static long guvenli_kopyala(char *hedef, unsigned long n, const char *kaynak) {
    unsigned long u = (unsigned long)strlen(kaynak);
    if (u + 1UL > n) return -1L;          /* sigmiyor: hic kopyalama yapma */
    memcpy(hedef, kaynak, (size_t)(u + 1UL));
    return (long)u;
}

int main(void) {
    char kucuk[8];
    const char *girdi[] = { "abc", "1234567", "12345678", "sistem" };
    for (int i = 0; i < 4; i++) {
        unsigned long u = (unsigned long)strlen(girdi[i]);
        long r = guvenli_kopyala(kucuk, (unsigned long)sizeof kucuk, girdi[i]);
        if (r < 0)
            printf("\"%s\" (%lu bayt + NUL) -> REDDEDILDI (hedef %lu bayt)\n",
                   girdi[i], u, (unsigned long)sizeof kucuk);
        else
            printf("\"%s\" -> kopyalandi (%ld bayt), hedef=\"%s\"\n",
                   girdi[i], r, kucuk);
    }
    return 0;
}
